def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Median of this
    list.

    >>> median([0,1,2,3,4,5])
    3.0
    """
    if len(numbers) == 0:
        raise ValueError("median(): empty data not allowed!")
    numbers.sort()
    mid = len(numbers) // 2
    if len(numbers) % 2:
        return numbers[mid]
    return (numbers[mid - 1] + numbers[mid]) / 2.0


