def median_absolute_deviation(numbers: List[float]) -> float:
    """For a given list of numbers, calculate Median Absolute Deviation (MAD)
    around the median of this dataset:
    MAD = median(|x - medx|)
    """
    medianx = median(numbers)
    return median(abs(x - medianx) for x in numbers)


