def filter_none(dicts: List[dict], keys: List[str]):
    """ Filter list of dicts only those which have any of the keys passed
    in the argument.
    """
    filtered_dicts = []

    for dict in dicts:
        for key in keys:
            if key not in dict:
                continue

            return_filtered_keys = []

            return_filtered_keys.append(key)
            return_filtered_keys.append(dict[key])

            filtered_dicts.append({key: return_filtered_keys})

    return filtered_dicts


def filter_string(strings: List[str], key: str) -> List[str]:
    """ Filter an input list of strings for strings having specified key """
    return_list = []

    for strng in strings:
        filtered_strng = ""

        for s in strng:
            if s not in {"a", "e", "i", "o", "u"}:
                filtered_strng += s

        if key.lower() in filtered_strng.lower():
            return_list.append(strng)

    return return_list
